const $ = s => document.querySelector(s);
const uid = () => crypto.randomUUID();
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const iso = d => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const date = s => new Date(s+'T12:00:00');
const add = (s,n) => {const d=date(s);d.setDate(d.getDate()+n);return iso(d)};
const fmt = (s,opts={day:'numeric',month:'short'}) => date(s).toLocaleDateString('it-IT',opts);
const today=iso(new Date());
const meals=[['Colazione','☕','Un buon inizio'],['Spuntino mattina','🍎','Una piccola pausa'],['Pranzo','🍽️','La tua pausa pranzo'],['Spuntino pomeriggio','🥝','Ricarica il pomeriggio'],['Cena','🥣','Concludi la giornata']];
const food=(name,icon,quantity='',groups=[],calories=null)=>({id:uid(),name,icon,quantity,groups,calories});
const group=(name,mode,options)=>({id:uid(),name,mode,options});
function sample(){return {id:uid(),name:'Il mio equilibrio',start:'2026-09-01',end:'2026-10-05',meals:[
 [group('La tua base','one',[food('Fette biscottate','🍞','Quantità da personalizzare',[group('Da spalmare','one',[food('Miele','🍯'),food('Marmellata','🫙')])]),food('Pane','🥖','Integrale o ai cereali',[group('Accompagna con','one',[food('Prosciutto','🍖'),food('Salmone','🐟')])])])],
 [group('Una pausa fresca','one',[food('Mela','🍎'),food('Pera','🍐'),food('Yogurt','🥛')])],
 [group('Scegli il tuo pranzo','one',[food('Pasta e verdure','🍝','Pranzo A',[group('Nel tuo piatto','all',[food('Pasta','🍝'),food('Zucchine','🥒'),food('Olio extravergine','🫒')])]),food('Riso e proteine','🍚','Pranzo B',[group('La base','all',[food('Riso','🍚'),food('Verdure','🥦')]),group('Una fonte proteica','one',[food('Pollo','🍗'),food('Ceci','🫘'),food('Tonno','🐟')])])])],
 [group('Scegli uno spuntino','one',[food('Mandorle','🌰'),food('Banana','🍌'),food('Yogurt','🥛')])],
 [group('La tua proteina','one',[food('Pesce','🐟'),food('Uova','🥚'),food('Tofu','🧊')]),group('Accompagna con','all',[food('Verdure','🥬'),food('Pane','🥖')])]
 ]};}
const key='germoglio-v1';
let state;try{state=JSON.parse(localStorage.getItem(key));if(!state||!Array.isArray(state.diets)||!state.logs)throw Error();}catch{state={diets:[sample()],logs:{}}}
let page='home',selected=today,month=selected.slice(0,7),mealIndex=0,choices={},mealOther=null,stage=0,draft=null,editMeal=0,iconTarget=null;
function save(){try{localStorage.setItem(key,JSON.stringify(state));return true}catch{toast('Spazio di archiviazione non disponibile. Le modifiche restano solo in questa sessione.');return false}}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3800)}
const active = (s=selected)=>state.diets.filter(d=>d.start<=s&&d.end>=s).sort((a,b)=>(b.priority||0)-(a.priority||0)||b.start.localeCompare(a.start))[0];
const logKey = (d,i,s=selected)=>`${d.id}:${s}:${i}`;
function week(s){const d=date(s);return Array.from({length:7},(_,i)=>add(s,i-(d.getDay()+6)%7))}
const svg = name=>{const paths={home:'<path d="m3 10 9-7 9 7v10H5V10M9 20v-7h6v7"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18"/>',chart:'<path d="M5 21V12h3v9m4 0V7h3v14m4 0V3h3v18"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="white"/><circle cx="16" cy="17" r="3" fill="white"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${paths[name]}</svg>`};
function shell(content){return `<div class="shell"><aside class="sidebar"><div class="brand"><span>🌱</span> germoglio</div><nav class="nav" aria-label="Navigazione principale">${[['home','home','Alimentazione'],['progress','chart','Progressi'],['plans','calendar','Piano'],['settings','settings','Altro']].map(([p,ic,t])=>`<button data-action="nav" data-page="${p}" class="${page===p||(page==='meal'&&p==='home')||(page==='editor'&&p==='plans')?'active':''}" ${page===p?'aria-current="page"':''}>${svg(ic)}<span>${t}</span></button>`).join('')}</nav><div class="sidebar-note">UN GIORNO ALLA VOLTA<br>Il tuo piano, le tue scelte.<br><br>Salvato su questo dispositivo</div></aside><main>${content}</main></div>`}
function home(){const diet=active(),done=diet?meals.filter((_,i)=>state.logs[logKey(diet,i)]||(typeof freeFor==='function'&&freeFor(selected,i)?.completed)).length:0;return `<header class="topline"><div><div class="eyebrow">Il tuo benessere quotidiano</div><h1 class="greeting">Ciao, prenditi cura di te<span style="color:#64956b">.</span></h1><p class="muted" style="margin-top:9px">Ogni scelta conta, oggi.</p></div><div class="avatar wide-only">🌱</div></header><div class="row"><span class="date-label">${fmt(selected,{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</span><div><button class="icon-button" data-action="week" data-n="-7" aria-label="Settimana precedente">‹</button> <button class="icon-button" data-action="week" data-n="7" aria-label="Settimana successiva">›</button></div></div><div class="week">${week(selected).map(s=>`<button class="day ${s===selected?'selected':''}" data-action="date" data-date="${s}" aria-label="${fmt(s,{weekday:'long',day:'numeric',month:'long'})}" aria-pressed="${s===selected}"><span>${fmt(s,{weekday:'short'}).replace('.','')}</span><strong>${date(s).getDate()}</strong><i class="dot" style="opacity:${active(s)?1:0}"></i></button>`).join('')}</div><div class="content-grid"><div><section class="card summary"><div class="ring" style="--p:${done*20}"><div><strong>${done*20}%</strong><small>completato</small></div></div><div><h3>${done===5?'Una giornata completa!':'Un pasto alla volta'}</h3><p class="muted" style="margin-top:5px">${done} di 5 pasti registrati oggi</p><p style="font-size:12px;color:#66856e;margin-top:7px">${done===0?'Il prossimo passo comincia da te.':'Continua con il tuo ritmo.'}</p></div></section><div class="row section-head"><h2>I pasti di oggi</h2><span class="muted">${diet?'5 momenti per te':'Nessun piano'}</span></div>${diet?`<div class="meal-list">${meals.map(([name,icon,sub],i)=>{const log=state.logs[logKey(diet,i)];return `<button class="meal" data-action="meal" data-index="${i}"><span class="meal-icon">${icon}</span><div class="meal-text"><h3>${name}</h3><p>${log?esc(log.items.map(o=>o.name).join(' · ')):sub}</p><div class="progress"><i style="width:${log?100:0}%"></i></div></div><span class="status ${log?'done':''}">${log?'✓':''}</span><span class="chevron">›</span></button>`}).join('')}</div>`:`<div class="card empty"><span class="food-icon">🗓️</span>Nessuna dieta valida per questa data.<br><button class="text-button" data-action="nav" data-page="plans">Scegli o crea un piano →</button></div>`}<div class="tiny-stats"><span><strong>${done}</strong> pasti completati</span><span><strong>${5-done}</strong> da comporre</span><span>✦ Il tuo ritmo</span></div></div><aside class="aside"><section class="card plan-card"><div class="row"><span class="eyebrow">Il tuo piano</span><span class="pill">${diet?'IN CORSO':'DA SCEGLIERE'}</span></div><div class="plan-art">🌿</div><h2 style="margin:16px 0 9px">${diet?esc(diet.name):'Il prossimo inizio'}</h2><p class="note">${diet?`${fmt(diet.start)} — ${fmt(diet.end,{day:'numeric',month:'short',year:'numeric'})}`:'Organizza i tuoi pasti e le alternative.'}</p><button class="text-button" data-action="nav" data-page="plans">Visualizza il piano <span>↗</span></button></section><section class="card aside-tip"><span style="font-size:25px">💡</span><h3 style="margin:12px 0 8px">Il piacere di scegliere</h3><p class="note">Ogni pasto può avere più alternative. Aprilo e scegli la combinazione che preferisci.</p></section></aside></div>`}
function chosen(g){return g.mode==='all'?g.options:g.options.filter(o=>(choices[g.id]||[]).includes(o.id))}
function valid(gs){return gs.length>0&&gs.every(g=>g.options.length>0&&(g.mode==='all'||chosen(g).length===1)&&chosen(g).every(o=>!o.groups.length||valid(o.groups)))}
function flatten(gs){return gs.flatMap(g=>chosen(g).flatMap(o=>[{name:o.name,icon:o.icon,quantity:o.quantity,calories:o.calories??null},...flatten(o.groups)]))}
function picker(gs){return gs.map(g=>`<section class="group"><div class="group-head"><h3>${esc(g.name)}</h3><small>${g.mode==='one'?'Scegli un’opzione':'Da aggiungere insieme'}</small></div><div class="options">${g.options.map(o=>{const checked=chosen(g).includes(o);return `<button class="option ${checked?'selected':''}" data-action="choose" data-group="${g.id}" data-option="${o.id}" aria-pressed="${checked}" ${g.mode==='all'?'disabled':''}><span class="check">${checked?'✓':''}</span><span class="food-icon">${o.icon}</span><strong>${esc(o.name)}</strong><small>${esc(o.quantity|| (o.groups.length?'Scopri gli abbinamenti':''))}</small></button>`}).join('')}</div>${chosen(g).filter(o=>o.groups.length).map(o=>`<div class="nested"><div class="nested-title">CON ${esc(o.name).toUpperCase()}</div>${picker(o.groups)}</div>`).join('')}</section>`).join('')}
function mealPage(){const diet=active();if(!diet)return home();const gs=diet.meals[mealIndex],items=flatten(gs);return `<div class="page-narrow"><button class="back" data-action="nav" data-page="home">‹ Torna alla giornata</button><div class="row"><div><div class="eyebrow">${fmt(selected)} · ${esc(diet.name)}</div><h1 style="margin-top:10px">${meals[mealIndex][0]}</h1><p class="muted" style="margin-top:7px">${stage===0?'Crea il tuo pasto':'Un ultimo sguardo al tuo piatto'}</p></div><span class="meal-icon">${meals[mealIndex][1]}</span></div><div class="steps"><span class="${stage===0?'on':''}">1 &nbsp; Componi</span><span class="${stage===1?'on':''}">2 &nbsp; Rivedi</span><span>3 &nbsp; Conferma</span></div>${stage===0?gs.length?picker(gs):`<div class="empty">Questo pasto non ha ancora opzioni.<br><button class="text-button" data-action="edit" data-id="${diet.id}">Configura il pasto →</button></div>`:`<section class="card"><h2>Il tuo pasto</h2>${items.map(o=>`<div class="review-item"><span style="font-size:26px">${o.icon}</span><div><h3>${esc(o.name)}</h3><p class="muted">${esc(o.quantity)}</p></div></div>`).join('')}<button class="text-button" data-action="stage" data-stage="0">‹ Modifica le scelte</button></section>`}<div class="note-box">${stage===0?'💡 Scegli un’opzione in ogni gruppo. Gli abbinamenti appariranno in base alle tue scelte.':'Conferma dopo aver consumato il pasto: lo ritroverai nella tua giornata.'}</div><div class="meal-footer"><button class="primary full" data-action="${stage===0?'review':'confirm'}" ${!valid(gs)?'disabled':''}>${stage===0?'Continua':'Conferma pasto'} <span style="float:right">→</span></button></div>${state.logs[logKey(diet,mealIndex)]?'<button class="text-button danger" data-action="unlog">Annulla registrazione del pasto</button>':''}</div>`}
function plans(){const first=date(month+'-01'),offset=(first.getDay()+6)%7,days=new Date(first.getFullYear(),first.getMonth()+1,0).getDate();return `<header class="topline"><div><div class="eyebrow">Organizza il tuo percorso</div><h1 class="greeting">Il tuo piano</h1></div><button class="primary" data-action="new">+ Nuova dieta</button></header><section class="card"><div class="row"><h2 style="text-transform:capitalize">${fmt(month+'-01',{month:'long',year:'numeric'})}</h2><div><button class="icon-button" data-action="month" data-n="-1" aria-label="Mese precedente">‹</button> <button class="icon-button" data-action="month" data-n="1" aria-label="Mese successivo">›</button></div></div><div class="calendar">${['L','M','M','G','V','S','D'].map(d=>`<span class="weekday">${d}</span>`).join('')}${'<span></span>'.repeat(offset)}${Array.from({length:days},(_,i)=>{const s=month+'-'+String(i+1).padStart(2,'0');return `<button class="${active(s)?'in-plan ':''}${s===selected?'selected ':''}${s===today?'today':''}" data-action="calendar-date" data-date="${s}" aria-label="${fmt(s)}${active(s)?': '+esc(active(s).name):': nessuna dieta'}">${i+1}${active(s)?'<small>·</small>':''}</button>`}).join('')}</div><div class="row" style="margin-top:20px"><span class="muted">${fmt(selected)} · ${active()?esc(active().name):'Nessuna dieta'}</span><button class="text-button" data-action="nav" data-page="home">Apri giornata →</button></div></section><div class="row" style="margin-top:29px"><h2>Le tue diete</h2><span class="muted">${state.diets.length} piani</span></div><div class="diet-list">${state.diets.slice().sort((a,b)=>a.start.localeCompare(b.start)).map(d=>`<section class="card diet-item"><span class="meal-icon">🌿</span><div class="body"><span class="pill" style="background:#edf3e9">${d.start>today?'IN PROGRAMMA':d.end<today?'CONCLUSA':'IN CORSO'}</span><h3>${esc(d.name)}</h3><p class="muted">${fmt(d.start,{day:'numeric',month:'short',year:'numeric'})} — ${fmt(d.end,{day:'numeric',month:'short',year:'numeric'})}</p><button class="text-button" data-action="edit" data-id="${d.id}">Modifica piano →</button></div><button class="icon-button" data-action="diet-menu" data-id="${d.id}" aria-label="Altre azioni per ${esc(d.name)}">···</button></section>`).join('')||'<div class="empty">Crea la tua prima dieta e aggiungi i pasti.</div>'}</div><div class="note-box">Le date di inizio e fine sono incluse. Ogni giorno può appartenere a una sola dieta, per sapere sempre quale piano seguire.</div>`}
function findGroup(gs,id){for(const g of gs){if(g.id===id)return g;for(const o of g.options){const result=findGroup(o.groups,id);if(result)return result}}}
function findOption(gs,id){for(const g of gs)for(const o of g.options){if(o.id===id)return o;const result=findOption(o.groups,id);if(result)return result}}
function removeGroup(gs,id){const n=gs.findIndex(g=>g.id===id);if(n>=0){gs.splice(n,1);return}for(const g of gs)for(const o of g.options)removeGroup(o.groups,id)}
function editorGroups(gs){return gs.map(g=>`<section class="editor-group"><div class="row"><input aria-label="Nome del gruppo" value="${esc(g.name)}" data-field="group-name" data-id="${g.id}" placeholder="Es. La tua base"><button class="delete" data-action="delete-group" data-id="${g.id}" aria-label="Elimina gruppo">×</button></div><div class="mode"><button data-action="mode" data-id="${g.id}" data-mode="one" class="${g.mode==='one'?'active':''}">◉ Scegli uno</button><button data-action="mode" data-id="${g.id}" data-mode="all" class="${g.mode==='all'?'active':''}">✓ Tutti insieme</button></div><p class="note">${g.mode==='one'?'Questi alimenti o combinazioni sono alternativi tra loro.':'Questi alimenti vanno inclusi tutti nel pasto.'}</p><div class="editor-options">${g.options.map(o=>`<div class="editor-option"><div class="row"><button class="icon-pick" data-action="icon" data-id="${o.id}" aria-label="Scegli icona per ${esc(o.name)}">${o.icon}</button><div class="fields"><input aria-label="Nome alimento o combinazione" value="${esc(o.name)}" data-field="option-name" data-id="${o.id}" placeholder="Alimento o combinazione"><input aria-label="Quantità o descrizione" value="${esc(o.quantity)}" data-field="quantity" data-id="${o.id}" placeholder="Quantità o descrizione (facoltativa)"></div><button class="delete" data-action="delete-option" data-group="${g.id}" data-id="${o.id}" aria-label="Elimina opzione">×</button></div>${o.groups.length?`<div class="nested">${editorGroups(o.groups)}</div>`:''}<button class="small-button" data-action="add-child" data-id="${o.id}">+ Quando scelgo questo, aggiungi…</button></div>`).join('')}</div><button class="text-button" data-action="add-option" data-id="${g.id}">+ Aggiungi ${g.mode==='one'?'alternativa':'alimento'}</button></section>`).join('')}
function editor(){return `<div class="page-narrow"><button class="back" data-action="cancel-edit">‹ Torna ai piani</button><div class="eyebrow">Il piano, a modo tuo</div><h1 class="greeting">${state.diets.some(d=>d.id===draft.id)?'Modifica dieta':'Nuova dieta'}</h1><label for="diet-name">Nome della dieta</label><input id="diet-name" data-field="diet-name" value="${esc(draft.name)}" placeholder="Es. Piano di settembre" maxlength="100"><div class="fields-row"><div><label for="start">Valida dal</label><input id="start" type="date" data-field="start" value="${draft.start}"></div><div><label for="end">Fino al (incluso)</label><input id="end" type="date" data-field="end" value="${draft.end}"></div></div><div class="note-box">Le stesse opzioni saranno disponibili ogni giorno della dieta. Usa <b>Scegli uno</b> per le alternative e <b>Tutti insieme</b> per gli abbinamenti.</div><div class="editor-tabs" aria-label="Pasto da configurare">${meals.map(([n,ic],i)=>`<button class="${i===editMeal?'active':''}" data-action="edit-meal" data-index="${i}">${ic} ${n}</button>`).join('')}</div><div class="editor-meal"><h2>${meals[editMeal][0]}</h2>${editorGroups(draft.meals[editMeal])}<button class="secondary full" data-action="add-group">+ Aggiungi gruppo di alimenti</button></div><div id="edit-error" class="error" role="alert"></div><button class="primary full" data-action="save-diet">Salva dieta <span style="float:right">✓</span></button><p class="muted" style="text-align:center;margin-top:12px;font-size:12px">Le modifiche si applicano quando salvi.</p></div>`}
function progress(){const dates=week(selected),logs=Object.entries(state.logs).filter(([k])=>dates.includes(k.split(':')[1])&&active(k.split(':')[1])?.id===k.split(':')[0]),total=dates.reduce((n,s)=>n+(active(s)?5:0),0),pct=total?Math.round(logs.length/total*100):0;return `<header class="topline"><div><div class="eyebrow">I tuoi piccoli passi</div><h1 class="greeting">Progressi</h1><p class="muted" style="margin-top:9px">${fmt(dates[0])} — ${fmt(dates[6])}</p></div><div><button class="icon-button" data-action="week" data-n="-7" aria-label="Settimana precedente">‹</button> <button class="icon-button" data-action="week" data-n="7" aria-label="Settimana successiva">›</button></div></header><section class="card summary" style="background:#e9f2e9"><span style="font-size:45px">🌱</span><div><h2>${logs.length?'Ogni passo conta.':'Il tuo percorso inizia qui.'}</h2><p class="muted" style="margin-top:7px">${logs.length} pasti registrati su ${total} previsti</p></div></section><section class="card"><h3>Pasti registrati nella settimana</h3><div class="bars">${dates.map(s=>{const n=logs.filter(([k])=>k.split(':')[1]===s).length;return `<div class="bar"><b>${n}</b><i style="height:${n*22+3}px"></i>${fmt(s,{weekday:'short'})}</div>`}).join('')}</div></section><div class="stats-grid"><div class="card"><p class="muted">Completamento settimanale</p><strong>${pct}%</strong></div><div class="card"><p class="muted">Giornate complete</p><strong>${dates.filter(s=>logs.filter(([k])=>k.split(':')[1]===s).length===5).length} <span class="muted">/ ${dates.filter(s=>active(s)).length}</span></strong></div></div><div class="note-box">Questi numeri indicano i pasti che hai registrato. Non misurano l’aderenza nutrizionale alla dieta.</div>`}
function settings(){return `<div class="page-narrow"><div class="eyebrow">Il tuo spazio</div><h1 class="greeting">Altre informazioni</h1><section class="card" style="margin-top:25px"><h2>Una base da personalizzare</h2><p class="note" style="margin-top:14px">Il piano “Il mio equilibrio” è un esempio di configurazione. Inserisci alimenti e quantità del tuo piano prima di utilizzarlo.</p></section><section class="card" style="margin-top:16px"><h3>Salvataggio sul dispositivo</h3><p class="note" style="margin-top:10px">Diete e registrazioni restano in questo browser. Non sono sincronizzate con altri dispositivi. Cancellando i dati del browser verranno rimossi.</p><button class="text-button" data-action="export">Scarica una copia dei dati ↓</button></section><section class="card" style="margin-top:16px"><h3>Su iPhone</h3><p class="note" style="margin-top:10px">Apri l’app in Safari. Dal menu Condividi, scegli “Aggiungi alla schermata Home” per averla sempre a portata di mano.</p></section></div>`}
function render(){const views={home,plans,meal:mealPage,editor,progress,settings};$('#app').innerHTML=views[page]()}
function navigate(p){page=p;render();window.scrollTo(0,0);notifySection(p)}
function openMeal(i){const diet=active();if(!diet)return;mealIndex=i;const log=state.logs[logKey(diet,i)];choices=structuredClone(log?.choices||{});mealOther=structuredClone(log?.other||null);stage=0;navigate('meal')}
const iconCategories={'Pane e cereali':'🍞 🥖 🥐 🥯 🫓 🥨 🥞 🧇 🍚 🍝 🥣 🌾 🌽 🥔','Frutta':'🍎 🍏 🍐 🍊 🍋 🍌 🍉 🍇 🍓 🫐 🍈 🍒 🍑 🥭 🍍 🥝 🥥','Verdure e legumi':'🥑 🥦 🥬 🥒 🌶️ 🫑 🥕 🧅 🧄 🍆 🍅 🍄 🫘 🫛 🫒','Proteine e latticini':'🥚 🍳 🍗 🍖 🥩 🥓 🐟 🍣 🍤 🦐 🧀 🥛 🧊','Dolci e frutta secca':'🍯 🫙 🌰 🥜 🍪 🍫 🍰 🧁 🍦 🍮','Integratori':'💊 🧴 🥄 💧', 'Bevande e piatti':'☕ 🍵 🫖 🧃 🥤 💧 🍽️ 🥗 🍲 🥘 🥪 🌮 🍕 🍱'};
function icons(){showModal(`<div class="row"><h2>Scegli un’icona</h2><button class="icon-button" data-action="close" aria-label="Chiudi">×</button></div>${Object.entries(iconCategories).map(([name,icons])=>`<h3 style="margin-top:22px;font-size:14px">${name}</h3><div class="icon-grid">${icons.split(' ').map(ic=>`<button data-action="set-icon" data-icon="${ic}" aria-label="Usa icona ${ic}">${ic}</button>`).join('')}</div>`).join('')}`)}
function showModal(html){$('#modal').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function validateDraft(){if(!draft.name.trim())return'Inserisci un nome per la dieta.';if(!/^\d{4}-\d{2}-\d{2}$/.test(draft.start)||!/^\d{4}-\d{2}-\d{2}$/.test(draft.end))return'Inserisci entrambe le date.';if(draft.start>draft.end)return'La data finale deve essere uguale o successiva a quella iniziale.';if(state.diets.some(d=>d.id!==draft.id&&!d.overrides?.includes(draft.id)&&!draft.overrides?.includes(d.id)&&d.start<=draft.end&&d.end>=draft.start))return'Queste date si sovrappongono a un’altra dieta. Scegli un periodo libero.';const good=gs=>gs.every(g=>g.name.trim()&&g.options.length&&g.options.every(o=>o.name.trim()&&good(o.groups)));for(let i=0;i<5;i++)if(!draft.meals[i].length||!good(draft.meals[i]))return`Completa ${meals[i][0]}: serve almeno un gruppo con opzioni, tutte con un nome.`;return''}
document.addEventListener('input',e=>{const f=e.target.dataset.field;if(!f||!draft)return;const value=e.target.value,id=e.target.dataset.id,gs=draft.meals[editMeal];if(f==='diet-name')draft.name=value;else if(f==='start'||f==='end')draft[f]=value;else if(f==='group-name')findGroup(gs,id).name=value;else if(f==='option-name')findOption(gs,id).name=value;else if(f==='quantity')findOption(gs,id).quantity=value});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id,gs=draft?.meals[editMeal];
 if(a==='nav'){if(page==='editor'){showModal(`<h2>Uscire dalla modifica?</h2><p class="note" style="margin-top:15px">Le modifiche non salvate andranno perse.</p><button class="primary full" data-action="discard" data-page="${b.dataset.page}">Esci senza salvare</button><button class="secondary full" data-action="close">Continua a modificare</button>`);return}navigate(b.dataset.page)}
 else if(a==='date'||a==='calendar-date'){selected=b.dataset.date;render()}
 else if(a==='week'){selected=add(selected,Number(b.dataset.n));month=selected.slice(0,7);render()}
 else if(a==='month'){const d=date(month+'-01');d.setMonth(d.getMonth()+Number(b.dataset.n));month=iso(d).slice(0,7);render()}
 else if(a==='meal')openMeal(Number(b.dataset.index));
 else if(a==='choose'){toggleChoice(b.dataset.group,b.dataset.option);render()}
 else if(a==='review'){if(valid(active().meals[mealIndex])){stage=1;render();window.scrollTo(0,0)}}
 else if(a==='stage'){stage=Number(b.dataset.stage);render()}
 else if(a==='confirm'){const d=active();if(!valid(d.meals[mealIndex]))return;const selectedItems=flatten(d.meals[mealIndex]);state.logs[logKey(d,mealIndex)]={choices:structuredClone(choices),other:mealOther?structuredClone(mealOther):null,items:[...selectedItems,...(mealOther?[{name:mealOther.description,icon:'➕',quantity:'Altro',calories:mealOther.calories}]:[])],limits:selectedLimits(d.meals[mealIndex]),omissions:typeof mealOmissions==='function'?mealOmissions(d.meals[mealIndex]):[],at:new Date().toISOString()};const ok=save();navigate('home');if(ok)toast('Pasto registrato')}
 else if(a==='unlog'){delete state.logs[logKey(active(),mealIndex)];save();navigate('home')}
 else if(a==='new'){draft={id:uid(),name:'',start:selected,end:add(selected,27),meals:meals.map(()=>[]),mealCalories:meals.map(()=>null)};editMeal=0;navigate('editor')}
 else if(a==='edit'){draft=structuredClone(state.diets.find(d=>d.id===id));editMeal=page==='meal'?mealIndex:0;navigate('editor')}
 else if(a==='edit-meal'){editMeal=Number(b.dataset.index);render()}
 else if(a==='add-group'){gs.push(group('Nuovo gruppo','one',[food('','🍽️')]));render()}
 else if(a==='add-child'){findOption(gs,id).groups.push(group('Abbina con','one',[food('','🍽️')]));render()}
 else if(a==='add-option'){findGroup(gs,id).options.push(food('','🍽️'));render()}
 else if(a==='delete-group'){removeGroup(gs,id);render()}
 else if(a==='delete-option'){const g=findGroup(gs,b.dataset.group);g.options=g.options.filter(o=>o.id!==id);render()}
 else if(a==='mode'){findGroup(gs,id).mode=b.dataset.mode;render()}
 else if(a==='icon'){iconTarget=id;icons()}
 else if(a==='set-icon'){findOption(gs,iconTarget).icon=b.dataset.icon;$('#modal').close();render()}
 else if(a==='close')$('#modal').close();
 else if(a==='save-diet'){const error=validateDraft();if(error){$('#edit-error').textContent=error;$('#edit-error').scrollIntoView({behavior:'smooth',block:'center'});return}const i=state.diets.findIndex(d=>d.id===draft.id);if(i>=0)state.diets[i]=structuredClone(draft);else state.diets.push(structuredClone(draft));selected=draft.start;month=selected.slice(0,7);const ok=save();draft=null;navigate('plans');if(ok)toast('Dieta salvata')}
 else if(a==='cancel-edit')showModal('<h2>Uscire dalla modifica?</h2><p class="note" style="margin-top:15px">Le modifiche non salvate andranno perse.</p><button class="primary full" data-action="discard" data-page="plans">Esci senza salvare</button><button class="secondary full" data-action="close">Continua a modificare</button>');
 else if(a==='discard'){draft=null;$('#modal').close();navigate(b.dataset.page)}
 else if(a==='diet-menu')showModal(`<h2>${esc(state.diets.find(d=>d.id===id).name)}</h2><button class="secondary full" data-action="duplicate" data-id="${id}">Duplica come nuova dieta</button><button class="text-button danger full" data-action="ask-delete" data-id="${id}">Elimina dieta</button><button class="secondary full" data-action="close">Chiudi</button>`);
 else if(a==='duplicate'){draft=structuredClone(state.diets.find(d=>d.id===id));draft.id=uid();delete draft.priority;delete draft.overrides;draft.name+=' · copia';draft.start=add(draft.end,1);draft.end=add(draft.start,27);editMeal=0;$('#modal').close();navigate('editor')}
 else if(a==='ask-delete')showModal(`<h2>Eliminare questa dieta?</h2><p class="note" style="margin-top:15px">Verranno eliminate anche le sue registrazioni. L’operazione non può essere annullata.</p><button class="primary full" data-action="delete-diet" data-id="${id}">Elimina dieta e registrazioni</button><button class="secondary full" data-action="close">Annulla</button>`);
 else if(a==='delete-diet'){state.diets=state.diets.filter(d=>d.id!==id);for(const k of Object.keys(state.logs))if(k.startsWith(id+':'))delete state.logs[k];save();$('#modal').close();render()}
 else if(a==='export'){const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='germoglio-'+today+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
});

if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'open_day',description:'Mostra il piano e i pasti per una data senza modificare i dati.',inputSchema:{type:'object',properties:{date:{type:'string',pattern:'^\\d{4}-\\d{2}-\\d{2}$'}},required:['date'],additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||typeof input.date!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(input.date)||Number.isNaN(date(input.date).getTime())||iso(date(input.date))!==input.date)throw Error('Data non valida');if(page==='editor')throw Error('Salva o annulla le modifiche prima di cambiare pagina');selected=input.date;month=selected.slice(0,7);navigate('home');return{date:selected,diet:active()?.name||null}}})).catch(()=>{})}catch{}}



/* Source: dieta/enhancements.js */
const previousUI={home,mealPage,progress,settings,render,editorGroups,validateDraft};
state.daily??={}; state.freeMeals??=[]; state.deviations??=[]; state.migrations??=[];
const weeklyRules={};
function weekUsage(keyName,s=selected,excludeCurrent=true){const days=week(s);return Object.entries(state.logs).filter(([k,l])=>days.includes(k.split(':')[1])&&active(k.split(':')[1])?.id===k.split(':')[0]&&(!excludeCurrent||k!==logKey(active(s)||{id:''},mealIndex,s))&&(l.limits||[]).includes(keyName)).length}
function limited(o){return !!o.weeklyLimit&&weekUsage(o.limitKey)>=o.weeklyLimit}
chosen=function(g){return g.options.filter(o=>(choices[g.id]||[]).includes(o.id))};
function groupValid(g){const picked=chosen(g);return g.options.length>0&&(g.mode==='one'?picked.length===1:g.mode==='all'?picked.length===g.options.length:picked.length>=(g.min??0))&&picked.every(o=>!limited(o)&&!o.needsConfirmation&&(!o.groups.length||valid(o.groups)))&&(!g.totalGrams||picked.reduce((n,o)=>n+Number(choices['grams:'+o.id]||0),0)===g.totalGrams&&picked.every(o=>Number(choices['grams:'+o.id])>0))}
valid=function(gs){return gs.length>0&&gs.every(groupValid)};
function selectedLimits(gs){return [...new Set(gs.flatMap(g=>chosen(g).flatMap(o=>[...(o.limitKey?[o.limitKey]:[]),...selectedLimits(o.groups)])))];}
function toggleChoice(gid,oid){const g=findGroup(active().meals[mealIndex],gid),o=g?.options.find(o=>o.id===oid);if(!o||limited(o))return;const ids=choices[gid]||[];choices[gid]=g.mode==='one'?[oid]:ids.includes(oid)?ids.filter(id=>id!==oid):[...ids,oid]}
flatten=function(gs){return gs.flatMap(g=>chosen(g).flatMap(o=>[{name:o.name,icon:o.icon,quantity:g.totalGrams?`${choices['grams:'+o.id]||0} g`:o.quantity,combo:o.combo,calories:o.calories??null},...flatten(o.groups)]))};
picker=function(gs){return gs.map(g=>{const sum=chosen(g).reduce((n,o)=>n+Number(choices['grams:'+o.id]||0),0);return `<section class="group"><div class="group-head"><h3>${esc(g.name)}</h3><small>${g.mode==='one'?'Scegli 1':g.mode==='all'?'Spunta ogni alimento':g.min?'Scegli uno o più':'Facoltativi · scegli zero o più'}</small></div><div class="options">${g.options.map(o=>{const checked=chosen(g).includes(o),disabled=limited(o)||o.needsConfirmation;return `<button class="option ${checked?'selected':''} ${disabled?'at-limit':''}" data-action="choose" data-group="${g.id}" data-option="${o.id}" aria-pressed="${checked}" ${disabled?'disabled':''}><span class="check">${checked?'✓':''}</span><span class="food-icon">${o.icon}</span><strong>${esc(o.name)}</strong><small>${esc(o.quantity)}</small>${o.weeklyLimit?`<small class="limit-label">${weekUsage(o.limitKey)}/${o.weeklyLimit} questa settimana${disabled?' · Limite raggiunto':''}</small>`:''}</button>`}).join('')}</div>${g.totalGrams?`<div class="vegetable-weights">${chosen(g).map(o=>`<label>${esc(o.name)} · grammi<input inputmode="numeric" type="number" min="1" max="${g.totalGrams}" step="1" data-grams="${o.id}" value="${esc(choices['grams:'+o.id]||'')}" placeholder="g"></label>`).join('')}<p class="${sum===g.totalGrams?'saved-tag':'muted'}">Totale: ${sum} / ${g.totalGrams} g</p><button class="secondary" data-action="apply-grams">Conferma quantità</button></div>`:''}${chosen(g).filter(o=>o.groups.length).map(o=>`<div class="nested"><div class="nested-title">${esc(o.name)}</div>${picker(o.groups)}</div>`).join('')}</section>`}).join('')};
function dailyData(){return state.daily[selected]??={water:0,omega:false,training:'',before:false,during:false}}
function freeFor(s,i){return state.freeMeals.find(f=>f.date===s&&f.meal===i)}
function tracker(){return ''}
home=function(){let html=previousUI.home();html=html.replace(/Un buon inizio|Una piccola pausa|La tua pausa pranzo|Ricarica il pomeriggio|Concludi la giornata/g,'Da completare');return html+tracker()};
mealPage=function(){const free=freeFor(selected,mealIndex);if(free)return `<div class="page-narrow"><button class="back" data-action="nav" data-page="home">‹ Torna alla giornata</button><h1>${meals[mealIndex][0]}</h1><section class="card" style="margin-top:20px"><span class="pill">Pasto libero programmato</span><h2 style="margin-top:15px">${esc(free.description)}</h2><p class="muted">${free.completed?'Completato':'Da completare'}</p><button class="primary full" data-action="toggle-free" data-id="${free.id}">${free.completed?'Segna da completare':'Conferma pasto libero'}</button><button class="text-button" data-action="remove-free" data-id="${free.id}">Annulla pianificazione</button></section></div>`;return previousUI.mealPage().replace('💡 Scegli un’opzione in ogni gruppo. Gli abbinamenti appariranno in base alle tue scelte.','I gruppi si aggiungono tra loro. Scegli una sola alternativa dove indicato e spunta tutti gli obbligatori.')};
progress=function(){const days=week(selected);return previousUI.progress()+`<section class="card" style="margin-top:20px"><h2>Limiti settimanali</h2><p class="muted">Lunedì–domenica · ${fmt(days[0])}–${fmt(days[6])}</p>${(typeof weeklyRuleEntries==='function'?weeklyRuleEntries():Object.entries(weeklyRules)).map(([k,[name,max]])=>`<div class="daily-row"><span>${name}</span><b>${weekUsage(k,selected,false)} / ${max}</b></div>`).join('')}<div class="daily-row"><span>Pasto libero programmato</span><b>${state.freeMeals.filter(f=>days.includes(f.date)).length} / ${typeof routineFor==='function'?routineFor(active()).freeLimit:1}</b></div><div class="daily-row"><span>Sgarri registrati</span><b>${state.deviations.filter(f=>days.includes(f.date)).length}</b></div></section>`};
editorGroups=function(gs){return previousUI.editorGroups(gs).replace(/<div class="mode">/g,'<div class="mode">')};
render=function(){previousUI.render();if(typeof document.querySelectorAll!=='function')return;
 if(page==='home')document.querySelectorAll('.meal').forEach((el,i)=>{const f=freeFor(selected,i),log=active()&&state.logs[logKey(active(),i)];const text=el.querySelector('.meal-text p');if(f){text.textContent=`Pasto libero · ${f.completed?'Completato':'Da completare'}`; const badge=el.querySelector('.status');badge.classList.toggle('done',f.completed);badge.textContent=f.completed?'✓':'';el.querySelector('.progress i').style.width=f.completed?'100%':'0%';}else if(log)text.textContent='Completato · '+log.items.map(o=>o.name).join(' · ')});
 if(page==='editor')document.querySelectorAll('.editor-group').forEach(el=>{const input=el.querySelector('[data-field="group-name"]'),g=findGroup(draft.meals[editMeal],input.dataset.id);const mode=el.querySelector('.mode');mode.innerHTML=['one','all','many'].map((m,i)=>`<button data-action="mode" data-id="${g.id}" data-mode="${m}" class="${g.mode===m?'active':''}">${['Scegli 1','Obbligatori','Multipla'][i]}</button>`).join('');el.querySelector('.note').textContent=g.mode==='one'?'Una sola alternativa.':g.mode==='all'?'Ogni alimento deve essere spuntato.':'Una o più scelte; minimo e quantità totali qui sotto.';if(g.mode==='many')mode.insertAdjacentHTML('afterend',`<div class="fields-row"><label>Scelte minime<input type="number" min="0" step="1" data-group-setting="min" data-id="${g.id}" value="${g.min||0}"></label><label>Totale grammi<input type="number" min="0" step="1" data-group-setting="totalGrams" data-id="${g.id}" value="${g.totalGrams||0}"></label></div>`)});
};
function specialForm(kind){const free=kind==='free';showModal(`<h2>${free?'Programma un pasto libero':'Registra uno sgarro'}</h2><label>Giorno<input id="special-date" type="date" value="${selected}"></label><label>Pasto<select id="special-meal">${meals.map(([name],i)=>`<option value="${i}">${name}</option>`).join('')}</select></label><label>Descrizione<input id="special-description" maxlength="300" placeholder="Alimenti e quantità"></label><p class="muted" style="margin-top:12px">${free?'Massimo '+(typeof routineFor==='function'?routineFor(active()).freeLimit:1)+' pasti liberi per settimana. Non vengono conteggiati come sgarri.':'Registrazione separata dal completamento del pasto.'}</p><p id="special-error" class="error" role="alert"></p><button class="primary full" data-action="save-special" data-kind="${kind}">Salva</button><button class="secondary full" data-action="close">Annulla</button>`)}
function saveSpecial(kind,s,i,description){if(!/^\d{4}-\d{2}-\d{2}$/.test(s)||Number.isNaN(date(s).getTime())||iso(date(s))!==s||!active(s)?.tracking)return'Scegli una data compresa in un piano attivo.';if(!Number.isInteger(i)||i<0||i>4||!description.trim())return'Inserisci pasto e descrizione.';if(kind==='free'){if(state.freeMeals.filter(f=>week(s).includes(f.date)).length>=(typeof routineFor==='function'?routineFor(active(s)).freeLimit:1))return'Hai già raggiunto il limite di pasti liberi di questa settimana.';if(state.logs[logKey(active(s),i,s)])return'Questo pasto è già registrato. Annulla la registrazione prima di programmarlo come libero.';state.freeMeals.push({id:uid(),date:s,meal:i,description:description.trim(),completed:false})}else state.deviations.push({id:uid(),date:s,meal:i,description:description.trim()});save();return''}
document.addEventListener('input',e=>{if(e.target.dataset.grams)choices['grams:'+e.target.dataset.grams]=e.target.value;if(e.target.dataset.groupSetting&&draft){const g=findGroup(draft.meals[editMeal],e.target.dataset.id);g[e.target.dataset.groupSetting]=Math.max(0,Math.floor(Number(e.target.value)||0))}});
