// Full plan editor: all edits stay on the draft until the existing Save action.
let editorUndo=[];
const defaultRoutine=()=>({waterTarget:2,waterNote:'Bevi a piccoli sorsi durante la giornata.',freeLimit:1,activities:['Allenamento','Camminata'],items:[
 {id:'routine-before',name:'Spuntino pre-allenamento',quantity:'Da personalizzare',timing:'Prima dell’allenamento'},
 {id:'routine-during',name:'Acqua',quantity:'Da personalizzare',timing:'Durante l’allenamento'}]});
function routineFor(d){return d?.routine||defaultRoutine()}
function routineChecked(d,id){const k='routine:'+id;if(d[k]===undefined)d[k]=id==='routine-before'?!!d.before:id==='routine-during'?!!d.during:false;return !!d[k]}
function prepareDraft(){if(draft&&!draft.routine)draft.routine=defaultRoutine();if(draft&&draft.tracking===undefined)draft.tracking=true;if(draft&&!Array.isArray(draft.mealCalories))draft.mealCalories=meals.map(()=>null);if(draft)walkOptions(draft.meals.flat()).forEach(o=>o.calories??=null)}
function walkOptions(gs){return gs.flatMap(g=>g.options.flatMap(o=>[o,...walkOptions(o.groups)]))}
function weeklyRuleEntries(d=active()){return d?walkOptions(d.meals.flat()).filter(o=>o.weeklyLimit>0).map(o=>[o.limitKey,[o.name,o.weeklyLimit]]):[]}
function rememberEdit(){if(draft){editorUndo.push(structuredClone(draft));if(editorUndo.length>30)editorUndo.shift()}}
function moveItem(items,id,delta){const i=items.findIndex(x=>x.id===id),j=i+delta;if(i<0||j<0||j>=items.length)return false;[items[i],items[j]]=[items[j],items[i]];return true}
function groupContainer(gs,id){if(gs.some(g=>g.id===id))return gs;for(const g of gs)for(const o of g.options){const found=groupContainer(o.groups,id);if(found)return found}}
function updateOptionSetting(id,field,value){if(!draft)return;const o=findOption(draft.meals[editMeal],id);if(!o)return;if(field==='weeklyLimit'){const v=Number(value);o.weeklyLimit=v;if(v>0)o.limitKey??='limit-'+o.id;}else if(field==='needsConfirmation')o.needsConfirmation=!!value;else if(field==='quantity'){o.quantity=value;delete o.needsConfirmation}else if(field==='calories')o.calories=value===''?null:Number(value)}
function editorOption(o,g,index){return `<article class="editor-option"><div class="row"><button class="icon-pick" data-action="icon" data-id="${o.id}" aria-label="Scegli icona per ${esc(o.name||'nuova voce')}">${o.icon}</button><div class="fields"><label>Alimento, integratore o combinazione<input aria-label="Nome alimento o combinazione" value="${esc(o.name)}" data-field="option-name" data-id="${o.id}" placeholder="Es. Pane, Omega-3, Pranzo A"></label><label>Quantità o descrizione<input aria-label="Quantità o descrizione" value="${esc(o.quantity)}" data-field="quantity" data-id="${o.id}" placeholder="Es. 80 g, 1 capsula, 2 cucchiai"></label><label>Calorie alimento (vuoto = non conteggiato)<input type="number" min="0" step="1" inputmode="numeric" value="${esc(o.calories??'')}" data-option-setting="calories" data-id="${o.id}" placeholder="Es. 240"></label></div></div><div class="toolbar editor-tools"><button data-action="move-option" data-group="${g.id}" data-id="${o.id}" data-delta="-1" ${index===0?'disabled':''} aria-label="Sposta su ${esc(o.name)}">↑ Su</button><button data-action="move-option" data-group="${g.id}" data-id="${o.id}" data-delta="1" ${index===g.options.length-1?'disabled':''} aria-label="Sposta giù ${esc(o.name)}">↓ Giù</button><button class="danger" data-action="delete-option" data-group="${g.id}" data-id="${o.id}">Elimina voce</button></div><details class="option-rules"><summary>Frequenza e quantità da verificare${o.weeklyLimit?' · max '+o.weeklyLimit+'/settimana':''}</summary><label>Massimo a settimana (0 = nessun limite)<input type="number" min="0" step="1" value="${o.weeklyLimit||0}" data-option-setting="weeklyLimit" data-id="${o.id}"></label><label class="checkbox-label"><input type="checkbox" data-option-setting="needsConfirmation" data-id="${o.id}" ${o.needsConfirmation?'checked':''}> Quantità ancora da verificare</label></details>${o.groups.length?`<details class="child-editor" open><summary>Abbinamenti quando scegli ${esc(o.name||'questa voce')}</summary><div class="nested">${editorGroups(o.groups)}</div></details>`:''}<button class="small-button" data-action="add-child" data-id="${o.id}">+ Aggiungi un gruppo di abbinamenti a questa voce</button></article>`}
editorGroups=function(gs){return gs.map((g,index)=>`<section class="editor-group"><label>Nome del gruppo<input aria-label="Nome del gruppo" value="${esc(g.name)}" data-field="group-name" data-id="${g.id}" placeholder="Es. Carboidrati, proteine, integratori"></label><div class="toolbar editor-tools"><button data-action="move-group" data-id="${g.id}" data-delta="-1" ${index===0?'disabled':''}>↑ Su</button><button data-action="move-group" data-id="${g.id}" data-delta="1" ${index===gs.length-1?'disabled':''}>↓ Giù</button><button class="danger" data-action="delete-group" data-id="${g.id}">Elimina gruppo</button></div><div class="mode">${['one','all','many'].map((m,i)=>`<button data-action="mode" data-id="${g.id}" data-mode="${m}" class="${g.mode===m?'active':''}" aria-pressed="${g.mode===m}">${['Scegli 1','Tutti insieme','Scelta multipla'][i]}</button>`).join('')}</div><p class="note">${g.mode==='one'?'Scegli una sola alternativa tra queste voci.':g.mode==='all'?'Queste voci vanno aggiunte tutte al pasto.':'Puoi scegliere più voci. Imposta 0 scelte minime per renderle facoltative.'}</p>${g.mode==='many'?`<div class="fields-row"><label>Scelte minime<input type="number" min="0" step="1" data-group-setting="min" data-id="${g.id}" value="${g.min||0}"></label><label>Totale grammi (0 = libero)<input type="number" min="0" step="1" data-group-setting="totalGrams" data-id="${g.id}" value="${g.totalGrams||0}"></label></div>`:''}<div class="editor-options">${g.options.map((o,i)=>editorOption(o,g,i)).join('')||'<p class="empty">Gruppo vuoto: aggiungi una voce oppure elimina il gruppo.</p>'}</div><button class="secondary full" data-action="add-option" data-id="${g.id}">+ Aggiungi ${g.mode==='one'?'alternativa':'voce'}</button></section>`).join('')};
function routineEditor(){const r=draft.routine;return `<details class="card routine-editor"><summary>Pasti liberi</summary><label>Pasti liberi / settimana<input type="number" min="0" step="1" value="${r.freeLimit}" data-routine-field="freeLimit"></label></details>`}
editor=function(){prepareDraft();return `<div class="page-narrow"><button class="back" data-action="cancel-edit">‹ Torna ai piani</button><h1>Modifica il tuo piano</h1><p class="muted" style="margin-top:10px">Puoi cambiare ogni voce. Le registrazioni già confermate conservano il loro riepilogo.</p><label for="diet-name">Nome dieta</label><input id="diet-name" data-field="diet-name" value="${esc(draft.name)}"><div class="fields-row"><div><label for="start">Valida dal</label><input id="start" type="date" data-field="start" value="${draft.start}"></div><div><label for="end">Fino al</label><input id="end" type="date" data-field="end" value="${draft.end}"></div></div><div class="editor-tabs" aria-label="Pasto da modificare">${meals.map(([name,icon],i)=>`<button data-action="edit-meal" data-index="${i}" class="${i===editMeal?'active':''}">${icon} ${name}</button>`).join('')}</div><div class="row"><h2>${meals[editMeal][0]}</h2><button class="small-button" data-action="undo-editor" ${editorUndo.length?'':'disabled'}>↶ Annulla ultima azione</button></div>${editorGroups(draft.meals[editMeal])||'<div class="empty">Nessuna voce in questo pasto. Aggiungi un gruppo per configurarlo.</div>'}<button class="secondary full" data-action="add-group">+ Aggiungi gruppo (carboidrati, proteine, integratori…)</button>${routineEditor()}<p id="edit-error" class="error" role="alert"></p><div class="editor-save"><button class="primary full" data-action="save-diet">Salva dieta ✓</button><p class="muted">Le modifiche valgono per tutto il periodo della dieta.</p></div></div>`};
validateDraft=function(){if(!draft?.name.trim())return'Inserisci un nome per la dieta.';if(![draft.start,draft.end].every(s=>/^\d{4}-\d{2}-\d{2}$/.test(s)&&!Number.isNaN(date(s).getTime())&&iso(date(s))===s)||draft.start>draft.end)return'Controlla le date di validità.';if(state.diets.some(d=>d.id!==draft.id&&d.start<=draft.end&&d.end>=draft.start&&!d.overrides?.includes(draft.id)&&!draft.overrides?.includes(d.id)))return'Le date si sovrappongono a un’altra dieta.';const check=gs=>gs.every(g=>g.name.trim()&&['one','all','many'].includes(g.mode)&&g.options.length&&(g.mode!=='many'||Number.isInteger(g.min??0)&&(g.min??0)>=0&&(g.min??0)<=g.options.length&&Number.isFinite(g.totalGrams||0)&&(g.totalGrams||0)>=0)&&g.options.every(o=>o.name.trim()&&Number.isInteger(o.weeklyLimit||0)&&(o.weeklyLimit||0)>=0&&check(o.groups)));if(!draft.meals.every(check))return'Completa i nomi, elimina i gruppi vuoti e controlla i limiti e le scelte minime.';const r=routineFor(draft);if(!Number.isFinite(r.waterTarget)||r.waterTarget<0||!Number.isInteger(r.freeLimit)||r.freeLimit<0||r.items.some(o=>!o.name.trim()))return'Controlla acqua, limite dei pasti liberi e nomi delle voci dell’allenamento.';return''};
const renderWithPlan=render;
render=function(){if(page==='editor'){$('#app').innerHTML=editor();return}renderWithPlan();if(typeof document.querySelectorAll!=='function')return;
 if(page==='meal'&&active()){document.querySelector('[data-action="clarify-oil"]')?.closest('.note-box')?.remove();document.querySelector('.page-narrow')?.insertAdjacentHTML('afterbegin',`<button class="secondary edit-meal-shortcut" data-action="edit" data-id="${active().id}">✎ Modifica questo pasto</button>`);const visible=gs=>gs.flatMap(g=>[...g.options,...chosen(g).flatMap(o=>visible(o.groups))]);const pending=visible(active().meals[mealIndex]).filter(o=>o.needsConfirmation);if(pending.length)document.querySelector('.meal-footer')?.insertAdjacentHTML('beforebegin',`<div class="note-box">Voci da verificare: ${pending.map(o=>esc(o.name)).join(', ')}. Apri “Modifica questo pasto” per cambiare la quantità o togliere la spunta “Quantità ancora da verificare”.</div>`)}
 if(page==='home'&&active()){document.querySelector('.plan-card')?.insertAdjacentHTML('beforeend',`<button class="secondary full" data-action="edit" data-id="${active().id}">✎ Modifica tutto il piano</button>`);document.querySelectorAll('.meal').forEach((el,i)=>{if(!state.logs[logKey(active(),i)]&&!freeFor(selected,i)){const groups=active().meals[i];el.querySelector('.meal-text p').textContent=groups.length?'Da completare · '+groups.map(g=>g.name).join(' + '):'Pasto non configurato'}})}
};
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;
 if(['edit','new','duplicate'].includes(a))editorUndo=[];
 if(!draft)return;
 if(['add-group','add-child','add-option','delete-group','delete-option','mode'].includes(a))rememberEdit();
 if(!['move-option','move-group','undo-editor','add-routine','delete-routine','move-routine'].includes(a))return;
 e.stopImmediatePropagation();prepareDraft();if(a==='undo-editor'){if(editorUndo.length)draft=editorUndo.pop()}else{rememberEdit();const gs=draft.meals[editMeal];if(a==='move-option')moveItem(findGroup(gs,b.dataset.group).options,id,Number(b.dataset.delta));if(a==='move-group')moveItem(groupContainer(gs,id),id,Number(b.dataset.delta));if(a==='add-routine')draft.routine.items.push({id:uid(),name:'',quantity:'',timing:''});if(a==='delete-routine')draft.routine.items=draft.routine.items.filter(o=>o.id!==id);if(a==='move-routine')moveItem(draft.routine.items,id,Number(b.dataset.delta))}render();
},true);
document.addEventListener('input',e=>{if(!draft)return;const d=e.target.dataset;prepareDraft();if(d.field==='quantity'){updateOptionSetting(d.id,'quantity',e.target.value);const check=e.target.closest('.editor-option')?.querySelector('[data-option-setting="needsConfirmation"]');if(check)check.checked=false}if(d.optionSetting)updateOptionSetting(d.id,d.optionSetting,e.target.type==='checkbox'?e.target.checked:e.target.value);if(d.routineField){const f=d.routineField;draft.routine[f]=['waterTarget','freeLimit'].includes(f)?Number(e.target.value):f==='activities'?e.target.value.split(',').map(s=>s.trim()).filter(Boolean):e.target.value}if(d.routineItem){const item=draft.routine.items.find(o=>o.id===d.id);if(item)item[d.routineItem]=e.target.value}});
const oldTracker=tracker;
tracker=function(){if(!active()?.tracking)return '';const legacy=oldTracker(),pos=legacy.indexOf('<section class="card" style="margin-top:16px">');return pos>=0?legacy.slice(pos):''};

