render=function(){
 renderBeforeFoodCalories();
 const diet=active();if(!diet)return;
 if(page==='home'){
  const consumed=dailyConsumedCalories(diet);
  const target=diet.dailyCalories;
  document.querySelector('.summary>div:nth-child(2)')?.insertAdjacentHTML('beforeend',`<p class="calorie-summary"><strong>${consumed.toLocaleString('it-IT')}</strong>${target==null?' kcal consumate':' / '+Number(target).toLocaleString('it-IT')+' kcal'}</p>`);
  document.querySelectorAll('.meal').forEach((element,index)=>{
   const log=state.logs[logKey(diet,index)],known=log&&(hasKnownCalories(log.items||[])||Object.keys(log.choices||{}).length>0),targetValue=diet.mealCalories?.[index];
   const value=known?caloriesForLog(log,diet.meals[index]):null;
   const label=value!=null?`${value.toLocaleString('it-IT')}${targetValue!=null?' / '+Number(targetValue).toLocaleString('it-IT'):''} kcal`:targetValue!=null?`target ${Number(targetValue).toLocaleString('it-IT')} kcal`:'';
   if(label)element.querySelector('h3')?.insertAdjacentHTML('beforeend',`<span class="meal-kcal">${label}</span>`);
  });
 }
 if(page==='meal'&&!freeFor(selected,mealIndex)){
  const total=selectedCalories(),target=diet.mealCalories?.[mealIndex];
  document.querySelector('.steps')?.insertAdjacentHTML('afterend',`<div class="meal-calorie-live"><strong>${total.toLocaleString('it-IT')}</strong>${target==null?' kcal selezionate':' / '+Number(target).toLocaleString('it-IT')+' kcal'}</div>`);
  document.querySelectorAll('.option[data-option]').forEach(element=>{
   const option=findOption(diet.meals[mealIndex],element.dataset.option);
   if(option?.calories!=null)element.insertAdjacentHTML('beforeend',`<span class="option-kcal">${Number(option.calories).toLocaleString('it-IT')} kcal</span>`);
  });
  if(stage===1){const items=flatten(diet.meals[mealIndex]);document.querySelectorAll('.review-item').forEach((element,index)=>{const item=items[index];if(item?.calories!=null)element.querySelector('div')?.insertAdjacentHTML('beforeend',`<p class="option-kcal">${Number(item.calories).toLocaleString('it-IT')} kcal</p>`)})}
  const otherHtml=mealOther
   ?`<div><strong>${esc(mealOther.description)}</strong><p class="muted">${Number(mealOther.calories).toLocaleString('it-IT')} kcal stimate</p></div><button class="text-button danger" data-action="remove-other">Rimuovi</button>`
   :`<div><strong>Altro</strong><p class="muted">Aggiungi un alimento fuori dalle opzioni.</p></div><button class="secondary" data-action="add-other">+ Inserisci</button>`;
  document.querySelector('.note-box')?.insertAdjacentHTML('beforebegin',`<section class="card meal-other"><div class="row">${otherHtml}</div></section>`);
 }
};

document.addEventListener('click',event=>{
 const button=event.target.closest?.('[data-action]');if(!button)return;
 if(button.dataset.action==='add-other')showModal(`<h2>Altro alimento</h2><label>Descrizione<input id="other-description" maxlength="160" placeholder="Es. Focaccia"></label><label>Calorie stimate<input id="other-calories" type="number" min="0" step="1" inputmode="numeric" placeholder="Es. 350"></label><p id="other-error" class="error"></p><button class="primary full" data-action="save-other">Aggiungi al pasto</button><button class="secondary full" data-action="close">Annulla</button>`);
 if(button.dataset.action==='save-other'){
  try{
   const description=$('#other-description').value.trim(),calories=DietFormat.calories($('#other-calories').value);
   if(!description)throw Error('Inserisci una descrizione.');if(calories==null)throw Error('Inserisci le calorie stimate.');
   mealOther={description,calories};$('#modal').close();render();
  }catch(error){$('#other-error').textContent=error.message}
 }
 if(button.dataset.action==='remove-other'){mealOther=null;render()}
});


