 state.extraFoods=state.extraFoods.filter(e=>e.id!==id);
 const d=active(item.date),log=d&&item.meal<XF_OFF_MEAL?state.logs[logKey(d,item.meal,item.date)]:null;
 if(log?.viaExtras&&!(log.items||[]).length&&!xfForMeal(item.date,item.meal).length)delete state.logs[logKey(d,item.meal,item.date)];
